static lstr L1110 = {0, 2164, "// std/process: running programs with options. The rest of the functions are built into the compiler.\012\012import * as Arrays from \"std/array\"\012import * as Spawn from \"std/internal/process\"\012\012/// Runs a program found through `PATH`, waits for it to end, and gives its exit code, standard output and\012/// standard error. A program that cannot start, or a `folder` that does not exist, is an `Err`, and one\012/// killed by a signal has the code 128 plus the signal. `input` is the text for the standard input, which\012/// is closed with `None`. `environment` lists variables to set as name and value pairs, and a later pair\012/// of a name wins. `removed` lists names the program does not get. `folder` is the working folder, with\012/// `None` the one of this process. With `inheritOutput` the program writes to the output of this process,\012/// in order with its own, and the captured text is empty. The input is written while the output is read,\012/// so neither blocks the program. The program is looked up in the `PATH` the program gets, after\012/// `removed` and `environment` apply; with no `PATH`, the system's default search decides. Every option\012/// has a default and is named in the call: `run(\"cat\", [], input: Some(text))`.\012export function run(\012  command: string,\012  arguments: Array<string>,\012  input: Option<string> = None,\012  environment: Array<#[string, string]> = [],\012  removed: Array<string> = [],\012  folder: Option<string> = None,\012  inheritOutput: bool = false,\012): Result<#[int, string, string], string> uses io, alloc {\012  // Each variable to set becomes one NAME=VALUE entry.\012  let added: Array<string> = []\012  for (const entry of Arrays.values(environment)) {\012    const #[name, value] = entry\012    Arrays.push(mutable added, `${name}=${value}`)\012  }\012\012  // The runtime takes the input and the folder as text, with a flag for the input.\012  let hasInput = false\012  let inputText = \"\"\012  if (input is Some(text)) {\012    hasInput = true\012    inputText = text\012  }\012  let folderText = \"\"\012  if (folder is Some(path)) {\012    folderText = path\012  }\012  return Spawn.run(\012    command,\012    arguments,\012    inputText,\012    hasInput,\012    added,\012    removed,\012    folderText,\012    inheritOutput,\012  )\012}\012"};
