static lstr L1130 = {0, 1620, "// std/option: helpers over the prelude Option.\012\012/// Returns `Some(f(value))` for `Some(value)`, and `None` for `None` without calling f.\012export function map<T, U, effect E>(\012  option: Option<T>,\012  f: (value: T) => U uses E,\012): Option<U> uses alloc, E {\012  return match (option) { Some(value) => Some(f(value)), None => None }\012}\012\012/// Returns the option that `f(value)` gives for `Some(value)`, and `None` for `None` without\012/// calling f.\012export function andThen<T, U, effect E>(\012  option: Option<T>,\012  f: (value: T) => Option<U> uses E,\012): Option<U> uses E {\012  return match (option) { Some(value) => f(value), None => None }\012}\012\012/// Returns the value of a `Some`, or fallback for `None`.\012export function withDefault<T>(option: Option<T>, fallback: T): T from option {\012  return match (option) { Some(value) => value, None => copy(fallback) }\012}\012\012/// Returns the option itself when it is a `Some`, and calls f for the result only when it is `None`.\012export function orElse<T, effect E>(\012  option: Option<T>,\012  f: () => Option<T> uses E,\012): Option<T> from option uses E {\012  return match (option) { Some(_) => option, None => f() }\012}\012\012/// Tells whether the option is a `Some`.\012export function isSome<T>(option: Option<T>): bool {\012  return option is Some(_)\012}\012\012/// Tells whether the option is `None`.\012export function isNone<T>(option: Option<T>): bool {\012  return option is None\012}\012\012/// Turns `Some(value)` into `Ok(value)` and `None` into `Err(error)`.\012export function okOr<T, F>(option: Option<T>, error: F): Result<T, F> from option uses alloc {\012  return match (option) { Some(value) => Ok(value), None => Err(copy(error)) }\012}\012"};
