static lstr L1464 = {0, 6327, "// std/internal/signal. SIGINT and SIGTERM as a descriptor the loop can wait on.\012//\012// The first start installs one handler per signal and opens a pipe (a socket\012// pair on Windows). The handler only writes one byte, 1 for SIGINT and 2 for\012// SIGTERM, so it stays async-signal-safe and stays installed: every signal\012// that comes adds a byte, and each take reads one. A signal that comes while\012// Process.run runs goes to the child as well and is recorded the same way\012// (std_process.c). The wait on the descriptor is the loop's (narra_loop_wait_io\012// in std_async_loop.c). Windows maps Ctrl-C to 1 and Ctrl-Break to 2 through\012// SetConsoleCtrlHandler.\012#include <errno.h>\012#include <fcntl.h>\012#ifdef _WIN32\012#include <winsock2.h>\012#include <ws2tcpip.h>\012#include <windows.h>\012#else\012#include <sched.h>\012#include <signal.h>\012#include <stdatomic.h>\012#include <unistd.h>\012#endif\012\012// 0 before the first start, 1 while a thread starts, 2 once it is done.\012static int narra_signal_state = 0;\012// The read end of the pipe, or the negated errno value of a failed start.\012static int64_t narra_signal_descriptor = -1;\012\012#ifdef _WIN32\012static SOCKET narra_signal_writer = INVALID_SOCKET;\012\012static BOOL WINAPI narra_signal_console_handler(DWORD event) {\012  unsigned char code;\012  if (event == CTRL_C_EVENT) {\012    code = 1;\012  } else if (event == CTRL_BREAK_EVENT) {\012    code = 2;\012  } else {\012    return FALSE;\012  }\012  send(narra_signal_writer, (const char*)&code, 1, 0);\012  return TRUE;\012}\012\012static int narra_signal_open(void) {\012  WSADATA data;\012  WSAStartup(MAKEWORD(2, 2), &data);\012  // A connected pair of loopback sockets: the handler thread sends, the loop reads.\012  SOCKET listener = socket(AF_INET, SOCK_STREAM, 0);\012  if (listener == INVALID_SOCKET) return EIO;\012  struct sockaddr_in address;\012  memset(&address, 0, sizeof(address));\012  address.sin_family = AF_INET;\012  address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);\012  int size = sizeof(address);\012  SOCKET reader = INVALID_SOCKET;\012  SOCKET writer = socket(AF_INET, SOCK_STREAM, 0);\012  if (writer == INVALID_SOCKET || bind(listener, (struct sockaddr*)&address, size) != 0 ||\012      listen(listener, 1) != 0 || getsockname(listener, (struct sockaddr*)&address, &size) != 0 ||\012      connect(writer, (struct sockaddr*)&address, size) != 0 ||\012      (reader = accept(listener, NULL, NULL)) == INVALID_SOCKET) {\012    if (writer != INVALID_SOCKET) closesocket(writer);\012    closesocket(listener);\012    return EIO;\012  }\012  closesocket(listener);\012  u_long nonblocking = 1;\012  ioctlsocket(reader, FIONBIO, &nonblocking);\012  ioctlsocket(writer, FIONBIO, &nonblocking);\012  SetHandleInformation((HANDLE)(uintptr_t)reader, HANDLE_FLAG_INHERIT, 0);\012  SetHandleInformation((HANDLE)(uintptr_t)writer, HANDLE_FLAG_INHERIT, 0);\012  narra_signal_writer = writer;\012  if (!SetConsoleCtrlHandler(narra_signal_console_handler, TRUE)) {\012    narra_signal_writer = INVALID_SOCKET;\012    closesocket(reader);\012    closesocket(writer);\012    return EIO;\012  }\012  narra_signal_descriptor = (int64_t)reader;\012  return 0;\012}\012\012static int64_t narra_signal_take(int64_t descriptor) {\012  unsigned char code;\012  int count = recv((SOCKET)descriptor, (char*)&code, 1, 0);\012  if (count == 1) return code;\012  return 0;\012}\012#else\012// Shared with std/internal/process, which records the signals of a running child too.\012#ifndef NARRA_SIGNAL_COMMON\012#define NARRA_SIGNAL_COMMON\012typedef void (*narra_signal_function)(int);\012static _Atomic int narra_signal_writer = -1;\012static _Atomic(narra_signal_function) narra_signal_handler_in_use = NULL;\012\012static void narra_signal_note(int number) {\012  int saved = errno;\012  int writer = atomic_load(&narra_signal_writer);\012  if (writer >= 0 && (number == SIGINT || number == SIGTERM)) {\012    unsigned char code = number == SIGINT \077 1 : 2;\012    ssize_t ignored = write(writer, &code, 1);\012    (void)ignored;\012  }\012  errno = saved;\012}\012#endif\012\012static int narra_signal_prepare(int descriptor) {\012  int flags = fcntl(descriptor, F_GETFL, 0);\012  if (flags < 0 || fcntl(descriptor, F_SETFL, flags | O_NONBLOCK) < 0) return errno;\012  if (fcntl(descriptor, F_SETFD, FD_CLOEXEC) < 0) return errno;\012  return 0;\012}\012\012static int narra_signal_open(void) {\012  // pipe2 would set both flags at once, but it is hidden under _POSIX_C_SOURCE.\012  int ends[2];\012  if (pipe(ends) < 0) return errno;\012  int failure = narra_signal_prepare(ends[0]);\012  if (failure == 0) failure = narra_signal_prepare(ends[1]);\012  if (failure != 0) {\012    close(ends[0]);\012    close(ends[1]);\012    return failure;\012  }\012  struct sigaction action;\012  memset(&action, 0, sizeof(action));\012  action.sa_handler = narra_signal_note;\012  sigemptyset(&action.sa_mask);\012  action.sa_flags = SA_RESTART;\012  atomic_store(&narra_signal_writer, ends[1]);\012  // Publish the handler before installing it, so a Process.run that ends meanwhile puts it back.\012  atomic_store(&narra_signal_handler_in_use, narra_signal_note);\012  struct sigaction previous;\012  if (sigaction(SIGINT, &action, &previous) < 0) failure = errno;\012  if (failure == 0 && sigaction(SIGTERM, &action, NULL) < 0) {\012    // Put SIGINT back, so Ctrl-C does not write to a pipe nobody reads.\012    failure = errno;\012    sigaction(SIGINT, &previous, NULL);\012  }\012  if (failure != 0) {\012    atomic_store(&narra_signal_handler_in_use, NULL);\012    atomic_store(&narra_signal_writer, -1);\012    close(ends[0]);\012    close(ends[1]);\012    return failure;\012  }\012  narra_signal_descriptor = ends[0];\012  return 0;\012}\012\012static int64_t narra_signal_take(int64_t descriptor) {\012  unsigned char code;\012  while (true) {\012    ssize_t count = read((int)descriptor, &code, 1);\012    if (count == 1) return code;\012    if (count < 0 && errno == EINTR) continue;\012    return 0;\012  }\012}\012#endif\012\012static int64_t narra_signal_start(void) {\012  // The first caller installs; the others wait until it is done and share the answer.\012  int expected = 0;\012  if (__atomic_compare_exchange_n(&narra_signal_state, &expected, 1, false, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) {\012    int failure = narra_signal_open();\012    if (failure != 0) narra_signal_descriptor = -(int64_t)failure;\012    __atomic_store_n(&narra_signal_state, 2, __ATOMIC_RELEASE);\012  } else {\012    while (__atomic_load_n(&narra_signal_state, __ATOMIC_ACQUIRE) != 2) {\012#ifdef _WIN32\012      Sleep(0);\012#else\012      sched_yield();\012#endif\012    }\012  }\012  return narra_signal_descriptor;\012}\012\012static lstr* narra_signal_message(int64_t error) {\012  return lstr_from_cstr(strerror((int)error));\012}\012"};
