static lstr L3687 = {0, 5, "E0423"};
static lstr L3688 = {0, 193, "A name imported with `import { name }` has the name of a function, constant or alias of this module.\012Fix: rename the import with `as`, as in `import { length as textLength } from \"std/string\"`."};
static lstr L3689 = {0, 5, "E0424"};
static lstr L3690 = {0, 186, "Two imports bring in the same name from different modules, so a call to that name would be ambiguous.\012Fix: rename one of them with `as`, as in `import { parse as parseJson } from \"...\"`."};
static lstr L3691 = {0, 5, "E0425"};
